package com.example.islandhome;
import android.app.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.media.*;import android.media.session.*;import android.os.*;import android.provider.Settings;import android.view.*;import android.widget.*;import java.util.*;
public class IslandService extends Service {
 public static IslandService instance;WindowManager wm;WindowManager.LayoutParams lp;LinearLayout panel,row;TextView title,artist;ImageButton prev,toggle,next;boolean expanded;MediaSessionManager manager;MediaController player;String note="Island Home",detail="No active player";PendingIntent action;Handler h=new Handler(Looper.getMainLooper());
 MediaController.Callback cb=new MediaController.Callback(){public void onPlaybackStateChanged(PlaybackState s){draw();}public void onMetadataChanged(MediaMetadata m){draw();}public void onSessionDestroyed(){setPlayer(null);refresh();}};
 MediaSessionManager.OnActiveSessionsChangedListener changed=list->select(list);
 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
 ComponentName listener(){return new ComponentName(this,IslandListener.class);}
 TextView label(int size){TextView v=new TextView(this);v.setTextColor(-1);v.setTextSize(size);v.setGravity(Gravity.CENTER);v.setMaxLines(1);v.setEllipsize(android.text.TextUtils.TruncateAt.END);return v;}
 ImageButton button(int resource,String description){ImageButton b=new ImageButton(this);b.setImageResource(resource);b.setColorFilter(Color.WHITE);b.setBackgroundColor(Color.TRANSPARENT);b.setContentDescription(description);row.addView(b,new LinearLayout.LayoutParams(0,dp(48),1));return b;}
 public void onCreate(){super.onCreate();NotificationManager nm=getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("island","Island media",NotificationManager.IMPORTANCE_LOW));PendingIntent p=PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);startForeground(1,new Notification.Builder(this,"island").setSmallIcon(android.R.drawable.ic_media_play).setContentTitle("Island running").setContentIntent(p).build());if(!Settings.canDrawOverlays(this)){stopSelf();return;}wm=getSystemService(WindowManager.class);panel=new LinearLayout(this);panel.setOrientation(1);panel.setGravity(Gravity.CENTER);panel.setPadding(dp(12),dp(4),dp(12),dp(4));GradientDrawable bg=new GradientDrawable();bg.setColor(Color.BLACK);bg.setCornerRadius(dp(28));panel.setBackground(bg);title=label(13);artist=label(12);panel.addView(title,new LinearLayout.LayoutParams(-1,dp(30)));panel.addView(artist,new LinearLayout.LayoutParams(-1,dp(24)));row=new LinearLayout(this);panel.addView(row);prev=button(android.R.drawable.ic_media_previous,"Previous track");toggle=button(android.R.drawable.ic_media_play,"Play");next=button(android.R.drawable.ic_media_next,"Next track");prev.setOnClickListener(v->command(0));toggle.setOnClickListener(v->command(1));next.setOnClickListener(v->command(2));panel.setOnClickListener(v->{expanded=!expanded;refresh();draw();});panel.setOnLongClickListener(v->{try{PendingIntent a=player==null?action:player.getSessionActivity();if(a!=null)a.send();}catch(Exception e){}return true;});lp=new WindowManager.LayoutParams(dp(174),dp(38),WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE,PixelFormat.TRANSLUCENT);lp.gravity=Gravity.TOP|Gravity.CENTER_HORIZONTAL;lp.y=dp(getSharedPreferences("home",0).getInt("islandY",4));try{wm.addView(panel,lp);}catch(Exception e){stopSelf();return;}instance=this;manager=getSystemService(MediaSessionManager.class);connectMedia();draw();}
 public void connectMedia(){if(manager==null)return;try{manager.removeOnActiveSessionsChangedListener(changed);manager.addOnActiveSessionsChangedListener(changed,listener(),h);refresh();}catch(SecurityException e){detail="Enable notification/media access";draw();}}
 void refresh(){if(manager==null)return;try{select(manager.getActiveSessions(listener()));}catch(SecurityException e){detail="Enable notification/media access";draw();}}
 void select(java.util.List<MediaController> list){if(list==null)list=Collections.emptyList();if(player!=null){for(MediaController c:list)if(c.getSessionToken().equals(player.getSessionToken())){draw();return;}}MediaController picked=null;for(MediaController c:list){PlaybackState s=c.getPlaybackState();if(s!=null&&s.getState()==PlaybackState.STATE_PLAYING){picked=c;break;}}if(picked==null&&!list.isEmpty())picked=list.get(0);setPlayer(picked);}
 void setPlayer(MediaController c){if(player!=null)try{player.unregisterCallback(cb);}catch(Exception e){}player=c;if(player!=null)player.registerCallback(cb,h);draw();}
 void command(int which){refresh();if(player==null){Toast.makeText(this,"Start a track in your music app first",1).show();return;}try{PlaybackState state=player.getPlaybackState();MediaController.TransportControls t=player.getTransportControls();if(which==0)t.skipToPrevious();else if(which==2)t.skipToNext();else if(state!=null&&state.getState()==PlaybackState.STATE_PLAYING)t.pause();else t.play();h.postDelayed(()->{refresh();draw();},400);}catch(Exception e){Toast.makeText(this,"Player could not accept this command",1).show();}}
 void enabled(View v,boolean on){v.setEnabled(on);v.setAlpha(on?1f:.35f);}
 void draw(){if(panel==null||lp==null)return;PlaybackState state=player==null?null:player.getPlaybackState();MediaMetadata meta=player==null?null:player.getMetadata();String name=meta==null?null:meta.getString(MediaMetadata.METADATA_KEY_TITLE);title.setText(player==null?note:(name==null?player.getPackageName():name));String a=meta==null?null:meta.getString(MediaMetadata.METADATA_KEY_ARTIST);artist.setText(player==null?detail:(a==null?"":a));artist.setVisibility(expanded?View.VISIBLE:View.GONE);row.setVisibility(expanded?View.VISIBLE:View.GONE);boolean playing=state!=null&&state.getState()==PlaybackState.STATE_PLAYING;toggle.setImageResource(playing?android.R.drawable.ic_media_pause:android.R.drawable.ic_media_play);toggle.setContentDescription(playing?"Pause":"Play");long actions=state==null?0:state.getActions();enabled(prev,player!=null&&(actions&PlaybackState.ACTION_SKIP_TO_PREVIOUS)!=0);enabled(next,player!=null&&(actions&PlaybackState.ACTION_SKIP_TO_NEXT)!=0);enabled(toggle,player!=null);lp.width=dp(expanded?Math.min(320,getResources().getConfiguration().screenWidthDp-20):174);lp.height=dp(expanded?112:38);try{wm.updateViewLayout(panel,lp);}catch(Exception e){}}
 public void update(String t,String b,PendingIntent p){h.post(()->{note=t;detail=b;action=p;refresh();});}
 public void reposition(){if(lp!=null){lp.y=dp(getSharedPreferences("home",0).getInt("islandY",4));draw();}}
 public int onStartCommand(Intent i,int f,int id){return START_NOT_STICKY;}public IBinder onBind(Intent i){return null;}
 public void onDestroy(){instance=null;h.removeCallbacksAndMessages(null);if(manager!=null)try{manager.removeOnActiveSessionsChangedListener(changed);}catch(Exception e){}if(player!=null)try{player.unregisterCallback(cb);}catch(Exception e){}if(wm!=null&&panel!=null)try{wm.removeView(panel);}catch(Exception e){}super.onDestroy();}
}
